public class JobMonitorAndNotify implements JobExecutionListener {

    @Override
    public void afterJob(JobExecution jobExecution) {
        if (jobExecution.getStatus() == BatchStatus.FAILED) {
            // Send notification (email, SMS, Kafka message, etc.)
            System.out.println("Job Failed! Sending alert...");
        }
    }
}

